param([string]$Fixture='',[string]$Install='')
$ErrorActionPreference='Stop'
$warlockProject=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$warlockWorkspace=[IO.Path]::GetFullPath((Join-Path $warlockProject '..'))
if(-not$Fixture){$Fixture=Join-Path $warlockProject '.cache/warlock-spell-diagnostics/20261103-084141636'}
if(-not$Install){$Install=[IO.Path]::GetFullPath((Join-Path $warlockWorkspace '../FullDecomp/NwnRootInstall'))}
$warlockGodot=Join-Path $warlockProject '.tools/Godot_v4.7.2-stable_win64.exe'
if((Get-FileHash -LiteralPath $warlockGodot -Algorithm SHA256).Hash-ne'AB1824F85BFD8E0E4128182C000C4003A3E042245B2967848D089B2A04B22424'){throw 'Unexpected runtime; no build/download'}
$warlockRun=Join-Path $warlockProject ('.cache/warlock-native-snapshot-tests/'+[DateTime]::UtcNow.ToString('yyyyMMdd-HHmmss')+'-'+[Guid]::NewGuid().ToString('N').Substring(0,8));$warlockCopy=Join-Path $warlockRun 'project';[IO.Directory]::CreateDirectory($warlockCopy)|Out-Null
$warlockClosure=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);$warlockPending=[Collections.Generic.Queue[string]]::new();$warlockPending.Enqueue('tests/native_cached_warlock_spells_test.gd')
while($warlockPending.Count){$relative=$warlockPending.Dequeue();if(-not$warlockClosure.Add($relative)){continue};$source=Join-Path $warlockProject $relative;if(-not(Test-Path -LiteralPath $source)){throw ('Missing static dependency '+$relative)};if($relative.EndsWith('.gd')){foreach($match in [regex]::Matches([IO.File]::ReadAllText($source),'res://([^"\r\n]+\.(?:gdshader|json|gd))"')){$warlockPending.Enqueue($match.Groups[1].Value)}}}
[void]$warlockClosure.Add('tools/test-native-cached-warlock-spells.ps1');$warlockInputs=@()
foreach($relative in ($warlockClosure|Sort-Object)){$source=Join-Path $warlockProject $relative;$destination=Join-Path $warlockCopy $relative;[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($destination))|Out-Null;$hash=(Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash.ToLowerInvariant();Copy-Item -LiteralPath $source -Destination $destination;if((Get-FileHash -LiteralPath $destination -Algorithm SHA256).Hash.ToLowerInvariant()-ne$hash){throw 'Changed during copy'};$warlockInputs+=@{path=$relative;sha256=$hash}}
$warlockFixture=Get-Content -LiteralPath (Join-Path $Fixture 'diagnostic.json') -Raw|ConvertFrom-Json;$warlockData=@()
foreach($entry in $warlockFixture.resources){$file=Join-Path $Fixture $entry.file;$actual=(Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash.ToLowerInvariant();if($actual-ne$entry.sha256){throw 'Changed cached fixture bytes'};$warlockData+=@{file=$file;sha256=$actual}}
[IO.File]::WriteAllText((Join-Path $warlockCopy 'project.godot'),"config_version=5`n[application]`nconfig/name=""Owned Cached Warlock State""`n[rendering]`nrenderer/rendering_method=""gl_compatibility""`n")
$warlockLog=Join-Path $warlockRun 'engine.log';$warlockOutput=Join-Path $warlockRun 'result.json';$info=[Diagnostics.ProcessStartInfo]::new();$info.FileName=$warlockGodot;$info.WorkingDirectory=$warlockWorkspace;$info.UseShellExecute=$false;$info.CreateNoWindow=$true;$info.WindowStyle=[Diagnostics.ProcessWindowStyle]::Hidden;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true
foreach($arg in @('--headless','--path',$warlockCopy,'--log-file',$warlockLog,'--script','res://tests/native_cached_warlock_spells_test.gd','--',('--fixture='+$Fixture),('--install='+$Install),('--report='+$warlockOutput),'--entity-api-rest=false')){$info.ArgumentList.Add($arg)}
$owned=$null;$stdout=$null;$stderr=$null;$timeout=$false
try{$owned=[Diagnostics.Process]::Start($info);$stdout=[IO.File]::Create((Join-Path $warlockRun 'stdout.log'));$stderr=[IO.File]::Create((Join-Path $warlockRun 'stderr.log'));$outTask=$owned.StandardOutput.BaseStream.CopyToAsync($stdout);$errTask=$owned.StandardError.BaseStream.CopyToAsync($stderr);if(-not$owned.WaitForExit(35000)){$timeout=$true;$owned.Kill($true);$owned.WaitForExit()};$null=$outTask.GetAwaiter().GetResult();$null=$errTask.GetAwaiter().GetResult();$owned.Refresh();$exit=$owned.ExitCode}finally{if($owned-and-not$owned.HasExited){$owned.Kill($true);$owned.WaitForExit()};if($stdout){$stdout.Dispose()};if($stderr){$stderr.Dispose()}}
$warlockResult=if(Test-Path -LiteralPath $warlockOutput){Get-Content -LiteralPath $warlockOutput -Raw|ConvertFrom-Json}else{$null};$clean=(Test-Path -LiteralPath $warlockLog)-and([IO.File]::ReadAllText($warlockLog)-notmatch '(?m)^ERROR:|^WARNING:|SCRIPT ERROR|Parse Error|ObjectDB instances leaked|Leaked instance|still in use at exit')
$changed=@($warlockInputs|Where-Object{(Get-FileHash -LiteralPath (Join-Path $warlockProject $_.path) -Algorithm SHA256).Hash.ToLowerInvariant()-ne$_.sha256});$copyChanged=@($warlockInputs|Where-Object{(Get-FileHash -LiteralPath (Join-Path $warlockCopy $_.path) -Algorithm SHA256).Hash.ToLowerInvariant()-ne$_.sha256});$dataChanged=@($warlockData|Where-Object{(Get-FileHash -LiteralPath $_.file -Algorithm SHA256).Hash.ToLowerInvariant()-ne$_.sha256})
$success=[bool]($warlockResult-and$warlockResult.success-and$exit-eq0-and-not$timeout-and$clean-and$changed.Count-eq0-and$copyChanged.Count-eq0-and$dataChanged.Count-eq0)
$receipt=@{success=$success;directory=$warlockRun;fixture=$Fixture;inputs=$warlockInputs;dataInputs=$warlockData;changedInputs=$changed;changedCopiedInputs=$copyChanged;changedData=$dataChanged;checks=if($warlockResult){$warlockResult.checks}else{0};exitCode=$exit;cleanEngine=$clean;timedOut=$timeout;result=$warlockOutput;engineLog=$warlockLog;scope='Cached Arelith Warlock physical row92 actual production Snapshot/State replay; no UI/render/server/levelup/current-live-rules claim';publicConnections=0;nativeBuilds=0;gpu=$false}
[IO.File]::WriteAllText((Join-Path $warlockRun 'runner.json'),($receipt|ConvertTo-Json -Depth 8));if($success){[IO.File]::WriteAllText((Join-Path $warlockProject 'reports/native-cached-warlock-spells-v1-receipt.json'),($receipt|ConvertTo-Json -Depth 8))};@{success=$success;directory=$warlockRun;checks=$receipt.checks;sourceInputs=$warlockInputs.Count;dataInputs=$warlockData.Count;cleanEngine=$clean;timedOut=$timeout;changedInputs=$changed.Count;changedCopiedInputs=$copyChanged.Count;changedData=$dataChanged.Count}|ConvertTo-Json
if(-not$success){throw ('Owned cached Warlock diagnosis rejected: '+$warlockRun)}
